from jsonb_to_recordset($c$[{"id": 1000401, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "HTTP x HTTPS.", "verso": "HTTPS é o HTTP com criptografia (TLS), protegendo os dados trafegados.", "explicacao": "O cadeado no navegador indica conexão HTTPS."}, {"id": 1000402, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "O que faz o DNS?", "verso": "Traduz nomes de domínio (ex.: gov.br) em endereços IP.", "explicacao": "Domain Name System."}, {"id": 1000403, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "Protocolos de e-mail: SMTP x POP3 x IMAP.", "verso": "SMTP: envia. POP3: baixa as mensagens para o dispositivo. IMAP: acessa as mensagens mantendo-as no servidor e sincronizadas.", "explicacao": "Clássico de prova."}, {"id": 1000404, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "Para que serve uma VPN?", "verso": "Criar um túnel criptografado sobre uma rede pública, simulando uma conexão privada.", "explicacao": "Muito usada para acesso remoto seguro à rede da instituição."}, {"id": 1000405, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "O que é a navegação anônima (privada)?", "verso": "Não guarda histórico, cookies e dados de formulário após fechar a janela. Não torna o usuário anônimo para sites ou provedor.", "explicacao": "Downloads e favoritos continuam salvos."}, {"id": 1000406, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "O que são cookies?", "verso": "Pequenos arquivos que os sites gravam no navegador para lembrar preferências, sessões e rastrear navegação.", "explicacao": "Não são vírus."}, {"id": 1000407, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "Atalho para alternar entre janelas abertas no Windows:", "verso": "Alt + Tab.", "explicacao": "Windows + D mostra a área de trabalho; Windows + L bloqueia o computador."}, {"id": 1000408, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "O que acontece com arquivo apagado com Shift + Delete?", "verso": "É excluído permanentemente, sem passar pela Lixeira.", "explicacao": "Pendrives e unidades de rede também não usam Lixeira."}, {"id": 1000409, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a fórmula =SOMA(A1:A5)?", "verso": "Soma os valores das células de A1 até A5.", "explicacao": "Dois-pontos = intervalo; ponto e vírgula = células separadas (A1;A5)."}, {"id": 1000410, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pares", "frente": "Referência relativa x absoluta no Excel.", "verso": "Relativa (A1) muda ao copiar a fórmula. Absoluta ($A$1) não muda.", "explicacao": "$A1 trava a coluna; A$1 trava a linha."}, {"id": 1000411, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que retorna =SE(A1>=7;\"Aprovado\";\"Reprovado\") quando A1 = 6?", "verso": "Reprovado.", "explicacao": "Estrutura: =SE(teste;valor_se_verdadeiro;valor_se_falso)."}, {"id": 1000412, "trilha": "policial", "materia": "inf", "assunto": "Word", "tipo": "pergunta", "frente": "Atalhos do Word para negrito, itálico e sublinhado:", "verso": "Ctrl + N, Ctrl + I e Ctrl + S (versão em português).", "explicacao": "Em inglês: Ctrl + B, Ctrl + I e Ctrl + U."}, {"id": 1000413, "trilha": "policial", "materia": "inf", "assunto": "Nuvem", "tipo": "pares", "frente": "IaaS x PaaS x SaaS.", "verso": "IaaS: infraestrutura (servidores virtuais). PaaS: plataforma para desenvolver e rodar aplicações. SaaS: software pronto usado pela internet (ex.: e-mail web).", "explicacao": "Modelos de serviço de computação em nuvem."}, {"id": 1000414, "trilha": "policial", "materia": "inf", "assunto": "Hardware", "tipo": "pares", "frente": "Memória RAM x ROM.", "verso": "RAM: volátil, guarda dados temporários em uso. ROM: não volátil, guarda instruções permanentes (como o firmware).", "explicacao": "Desligou o computador, a RAM se apaga."}, {"id": 1000415, "trilha": "policial", "materia": "inf", "assunto": "Busca", "tipo": "pergunta", "frente": "No Google, o que faz colocar a expressão entre aspas?", "verso": "Busca exatamente aquela sequência de palavras.", "explicacao": "Sinal de menos exclui termo (-palavra); site: restringe a um domínio."}, {"id": 1000416, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Negação de “P e Q”:", "verso": "“não P ou não Q”.", "explicacao": "Lei de De Morgan: ~(P ∧ Q) ≡ ~P ∨ ~Q."}, {"id": 1000417, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Negação de “P ou Q”:", "verso": "“não P e não Q”.", "explicacao": "Lei de De Morgan: ~(P ∨ Q) ≡ ~P ∧ ~Q."}, {"id": 1000418, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Negação de “Se P, então Q”:", "verso": "“P e não Q”.", "explicacao": "~(P → Q) ≡ P ∧ ~Q. A negação de condicional nunca é outra condicional."}, {"id": 1000419, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Equivalências de “Se P, então Q”:", "verso": "“Se não Q, então não P” (contrapositiva) e “não P ou Q”.", "explicacao": "P → Q ≡ ~Q → ~P ≡ ~P ∨ Q."}, {"id": 1000420, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quando a condicional “Se P, então Q” é falsa?", "verso": "Só quando P é verdadeira e Q é falsa.", "explicacao": "Mnemônico: “Vera Fischer é falsa” (V → F = F)."}, {"id": 1000421, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quando a bicondicional “P se e somente se Q” é verdadeira?", "verso": "Quando P e Q têm o mesmo valor lógico (ambas V ou ambas F).", "explicacao": "P ↔ Q."}, {"id": 1000422, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quando a disjunção exclusiva “ou P ou Q” é verdadeira?", "verso": "Quando P e Q têm valores diferentes.", "explicacao": "É a negação da bicondicional."}, {"id": 1000423, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quantas linhas tem a tabela-verdade de uma proposição com n proposições simples?", "verso": "2 elevado a n.", "explicacao": "Ex.: 3 proposições → 8 linhas."}, {"id": 1000424, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pares", "frente": "Tautologia x contradição x contingência.", "verso": "Tautologia: sempre verdadeira. Contradição: sempre falsa. Contingência: pode ser V ou F.", "explicacao": "Ex.: “P ou não P” é tautologia."}, {"id": 1000425, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Negação de “Todo A é B”:", "verso": "“Algum A não é B”.", "explicacao": "Também: “Existe A que não é B”."}, {"id": 1000426, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Negação de “Nenhum A é B”:", "verso": "“Algum A é B”.", "explicacao": "Também: “Existe A que é B”."}, {"id": 1000427, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Negação de “Algum A é B”:", "verso": "“Nenhum A é B”.", "explicacao": "Não confundir com “Algum A não é B”."}, {"id": 1000428, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pergunta", "frente": "O que é um argumento válido?", "verso": "Aquele em que, se as premissas forem verdadeiras, a conclusão é necessariamente verdadeira.", "explicacao": "Validade depende da forma, não da verdade das premissas."}, {"id": 1000429, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pares", "frente": "Modus ponens x modus tollens.", "verso": "Ponens: P → Q; P; logo Q. Tollens: P → Q; não Q; logo não P.", "explicacao": "Falácias: afirmar o consequente e negar o antecedente."}, {"id": 1000430, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Como calcular o número de anagramas de uma palavra sem letras repetidas?", "verso": "Fatorial do número de letras (n!).", "explicacao": "Com repetição, divide pelo fatorial das repetições: ARARA = 5!/(3!·2!) = 10."}, {"id": 1000431, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pares", "frente": "Arranjo x combinação.", "verso": "Arranjo: a ordem importa (pódio, senha). Combinação: a ordem não importa (comissão, grupo).", "explicacao": "C(n,p) = n! / (p!·(n−p)!)."}, {"id": 1000432, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantas duplas diferentes podem ser formadas com 8 pessoas?", "verso": "28.", "explicacao": "C(8,2) = 8·7/2."}, {"id": 1000433, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Princípio da casa dos pombos: quantas pessoas garantem duas nascidas no mesmo mês?", "verso": "13.", "explicacao": "12 meses + 1."}, {"id": 1000434, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Como se calcula a probabilidade de um evento?", "verso": "Casos favoráveis divididos pelos casos possíveis.", "explicacao": "P = favoráveis / possíveis, entre 0 e 1."}, {"id": 1000435, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pares", "frente": "Probabilidade de “A e B” (independentes) x “A ou B” (excludentes).", "verso": "“E”: multiplica as probabilidades. “Ou” (mutuamente excludentes): soma.", "explicacao": "Ex.: dois lançamentos de moeda darem cara: 1/2 · 1/2 = 1/4."}, {"id": 1000436, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Aumento de 10% seguido de desconto de 10%: o preço final volta ao original?", "verso": "Não. Fica 1% menor (1,1 × 0,9 = 0,99).", "explicacao": "Aumentos e descontos sucessivos se multiplicam, não se somam."}, {"id": 1000437, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Descontos sucessivos de 10% e 20% equivalem a quanto?", "verso": "28%.", "explicacao": "0,9 × 0,8 = 0,72 → restam 72%."}, {"id": 1000438, "trilha": "policial", "materia": "rl", "assunto": "Juros", "tipo": "pares", "frente": "Juros simples x compostos.", "verso": "Simples: juros sempre sobre o capital inicial (crescimento linear). Compostos: juros sobre juros (crescimento exponencial).", "explicacao": "M = C(1 + i·t) x M = C(1 + i)^t."}, {"id": 1000439, "trilha": "policial", "materia": "rl", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o termo geral de uma progressão aritmética?", "verso": "aₙ = a₁ + (n − 1)·r.", "explicacao": "Soma: Sₙ = (a₁ + aₙ)·n / 2."}, {"id": 1000440, "trilha": "policial", "materia": "rl", "assunto": "Conjuntos", "tipo": "pergunta", "frente": "Como calcular o número de elementos da união de dois conjuntos?", "verso": "n(A ∪ B) = n(A) + n(B) − n(A ∩ B).", "explicacao": "Subtrai a interseção para não contá-la duas vezes."}, {"id": 1000441, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pares", "frente": "Instrumentos perfurantes, cortantes e contundentes: que lesão produzem?", "verso": "Perfurante (agulha): punctória. Cortante (navalha): incisa. Contundente (bastão): contusa.", "explicacao": "Combinações: perfurocortante (faca) = perfuroincisa; cortocontundente (machado) = cortocontusa; perfurocontundente (projétil) = perfurocontusa."}, {"id": 1000442, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Que lesão produz um projétil de arma de fogo?", "verso": "Perfurocontusa.", "explicacao": "Instrumento perfurocontundente."}, {"id": 1000443, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pares", "frente": "Ferida de entrada x ferida de saída do projétil.", "verso": "Entrada: geralmente menor, bordas invertidas, orla de escoriação e enxugo. Saída: maior, irregular, bordas evertidas, sem orlas.", "explicacao": "A orla de enxugo é a sujeira do projétil deixada na pele."}, {"id": 1000444, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que caracteriza o tiro encostado?", "verso": "Ferida irregular e estrelada (câmara de mina de Hoffmann) e sinal de Puppe-Werkgaertner (marca da boca do cano).", "explicacao": "Os gases penetram sob a pele e a rompem."}, {"id": 1000445, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que indicam a zona de tatuagem e a zona de esfumaçamento?", "verso": "Tiro a curta distância. A tatuagem (grãos de pólvora incrustados) não sai com lavagem; o esfumaçamento (fuligem) sai.", "explicacao": "Ausência de ambas sugere tiro a distância."}, {"id": 1000446, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Qual a ordem de surgimento da rigidez cadavérica (Lei de Nysten)?", "verso": "Começa pela mandíbula e nuca, desce para tronco e membros superiores e depois inferiores.", "explicacao": "Inicia em 1 a 2 horas e se completa em cerca de 8 horas."}, {"id": 1000447, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Quando surgem e quando se fixam os livores cadavéricos?", "verso": "Surgem em 2 a 3 horas e se fixam em cerca de 8 a 12 horas.", "explicacao": "Ficam nas partes de declive; ajudam a saber se o corpo foi mudado de posição."}, {"id": 1000448, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Qual o primeiro sinal da putrefação?", "verso": "A mancha verde abdominal, geralmente na fossa ilíaca direita, entre 18 e 24 horas.", "explicacao": "Fases: cromática, gasosa, coliquativa e esqueletização."}, {"id": 1000449, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pares", "frente": "Fenômenos transformativos destrutivos x conservadores.", "verso": "Destrutivos: autólise, putrefação, maceração. Conservadores: mumificação, saponificação (adipocera), corificação.", "explicacao": "Mumificação: ambiente quente e seco; saponificação: úmido e argiloso."}, {"id": 1000450, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é cronotanatognose?", "verso": "A estimativa do tempo de morte.", "explicacao": "Usa resfriamento, rigidez, livores, putrefação, entre outros."}, {"id": 1000451, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pares", "frente": "Enforcamento x estrangulamento x esganadura.", "verso": "Enforcamento: laço acionado pelo peso do corpo. Estrangulamento: laço acionado por força externa. Esganadura: compressão do pescoço com as mãos.", "explicacao": "Esganadura é sempre homicida."}, {"id": 1000452, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "Como é o sulco do enforcamento típico?", "verso": "Oblíquo, ascendente em direção ao nó, descontínuo e mais profundo do lado oposto ao nó.", "explicacao": "No estrangulamento, o sulco é horizontal e contínuo."}, {"id": 1000453, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que é o cogumelo de espuma?", "verso": "Espuma branca e fina na boca e nariz, típica do afogamento com o corpo vivo ao entrar na água.", "explicacao": "Sinal de vitalidade no afogamento."}, {"id": 1000454, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pergunta", "frente": "O que é equimose e como evolui sua cor (espectro de Legrand du Saulle)?", "verso": "Extravasamento de sangue na pele. Cores: vermelha, violácea, azul, esverdeada e amarelada, até desaparecer.", "explicacao": "Ajuda a datar a lesão."}, {"id": 1000455, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pares", "frente": "Equimose x hematoma.", "verso": "Equimose: sangue infiltrado nos tecidos, sem formar coleção. Hematoma: coleção de sangue que forma relevo.", "explicacao": "O hematoma pode ser puncionado."}, {"id": 1000456, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "Que lesão é produzida por descarga elétrica de alta tensão natural (raio)?", "verso": "Sinal de Lichtenberg: figuras arboriformes na pele.", "explicacao": "Na energia elétrica industrial, a marca típica é a de Jellinek."}, {"id": 1000457, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "Quais os graus de queimadura?", "verso": "1º: eritema. 2º: flictena (bolhas). 3º: necrose de toda a pele. 4º: carbonização.", "explicacao": "Classificação de Hoffmann."}, {"id": 1000458, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Qual o método de identificação mais usado pela papiloscopia?", "verso": "Datiloscopia: análise das impressões digitais (sistema de Vucetich).", "explicacao": "Baseia-se na perenidade, imutabilidade, variabilidade e classificabilidade."}, {"id": 1000459, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Quais os tipos fundamentais de impressão digital no sistema de Vucetich?", "verso": "Arco, presilha interna, presilha externa e verticilo.", "explicacao": "Arco não tem delta; presilhas têm um delta; verticilo tem dois."}, {"id": 1000460, "trilha": "policial", "materia": "ml", "assunto": "Sexologia", "tipo": "pergunta", "frente": "O que é conjunção carnal para fins penais?", "verso": "A penetração do pênis na vagina, ainda que parcial.", "explicacao": "Outros atos são “ato libidinoso diverso”."}, {"id": 1000461, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pares", "frente": "Laudo x auto x parecer.", "verso": "Laudo: relatório escrito pelos próprios peritos. Auto: ditado pelo perito a um escrivão, durante o exame. Parecer: opinião técnica sobre um laudo, a pedido de alguém.", "explicacao": "Documentos médico-legais."}, {"id": 1000462, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pergunta", "frente": "Quais as partes do laudo pericial?", "verso": "Preâmbulo, quesitos, histórico, descrição, discussão, conclusão e resposta aos quesitos.", "explicacao": "A descrição (visum et repertum) é a parte mais importante."}, {"id": 1000463, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pares", "frente": "Morte encefálica: o que é?", "verso": "Parada total e irreversível das funções do encéfalo, que autoriza a retirada de órgãos para transplante.", "explicacao": "Lei 9.434/1997 e Resolução CFM 2.173/2017."}, {"id": 1000464, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é comoriência?", "verso": "Presunção de morte simultânea de duas ou mais pessoas, quando não se sabe quem morreu primeiro.", "explicacao": "Código Civil, art. 8º."}, {"id": 1000465, "trilha": "policial", "materia": "ml", "assunto": "Toxicologia", "tipo": "pergunta", "frente": "Qual o efeito do monóxido de carbono no sangue e que sinal deixa no cadáver?", "verso": "Liga-se à hemoglobina (carboxiemoglobina), impedindo o transporte de oxigênio. Deixa livores de cor vermelho-carmim.", "explicacao": "Intoxicação comum em incêndios e ambientes fechados."}, {"id": 1000466, "trilha": "policial", "materia": "est", "assunto": "Medidas", "tipo": "pares", "frente": "Média x mediana x moda.", "verso": "Média: soma dividida pela quantidade. Mediana: valor central dos dados ordenados. Moda: valor que mais se repete.", "explicacao": "A mediana sofre menos influência de valores extremos."}, {"id": 1000467, "trilha": "policial", "materia": "est", "assunto": "Dispersão", "tipo": "pergunta", "frente": "Qual a relação entre variância e desvio padrão?", "verso": "O desvio padrão é a raiz quadrada da variância.", "explicacao": "O desvio padrão fica na mesma unidade dos dados."}, {"id": 1000468, "trilha": "policial", "materia": "est", "assunto": "Dispersão", "tipo": "pergunta", "frente": "O que é a amplitude de um conjunto de dados?", "verso": "A diferença entre o maior e o menor valor.", "explicacao": "Medida de dispersão mais simples."}, {"id": 1000469, "trilha": "policial", "materia": "est", "assunto": "Variáveis", "tipo": "pares", "frente": "Variável qualitativa x quantitativa.", "verso": "Qualitativa: atributos (cor, sexo, tipo de crime). Quantitativa: números (idade, número de ocorrências).", "explicacao": "Quantitativa discreta (contagem) ou contínua (medição)."}, {"id": 1000470, "trilha": "policial", "materia": "est", "assunto": "Amostragem", "tipo": "pares", "frente": "População x amostra.", "verso": "População: todo o conjunto de interesse. Amostra: parte da população usada para estudá-la.", "explicacao": "Parâmetro descreve a população; estatística, a amostra."}, {"id": 1000471, "trilha": "policial", "materia": "cont", "assunto": "Fundamentos", "tipo": "pergunta", "frente": "Qual a equação fundamental do patrimônio?", "verso": "Ativo = Passivo + Patrimônio Líquido.", "explicacao": "O patrimônio líquido é a riqueza própria."}, {"id": 1000472, "trilha": "policial", "materia": "cont", "assunto": "Contas", "tipo": "pares", "frente": "Contas de natureza devedora x credora.", "verso": "Devedoras: ativo e despesas. Credoras: passivo, patrimônio líquido e receitas.", "explicacao": "Contas retificadoras têm natureza contrária ao grupo."}, {"id": 1000473, "trilha": "policial", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Qual o método de escrituração contábil adotado no Brasil?", "verso": "Método das partidas dobradas: não há débito sem crédito de igual valor.", "explicacao": "Atribuído a Luca Pacioli."}, {"id": 1000474, "trilha": "policial", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "O que mostra o balanço patrimonial?", "verso": "A posição patrimonial e financeira da entidade numa data: ativo, passivo e patrimônio líquido.", "explicacao": "A DRE mostra o resultado do período."}, {"id": 1000475, "trilha": "policial", "materia": "cont", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o regime de competência?", "verso": "Receitas e despesas são reconhecidas no período em que ocorrem, independentemente de recebimento ou pagamento.", "explicacao": "O regime de caixa considera a entrada e saída de dinheiro."}, {"id": 1000476, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "Como o Estatuto da Igualdade Racial define a população negra?", "verso": "O conjunto de pessoas que se autodeclaram pretas e pardas, conforme o quesito cor ou raça do IBGE.", "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, IV."}, {"id": 1000477, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O que é discriminação racial pelo Estatuto?", "verso": "Toda distinção, exclusão, restrição ou preferência baseada em raça, cor, descendência ou origem nacional ou étnica que anule ou restrinja direitos em igualdade de condições.", "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, I."}, {"id": 1000478, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pares", "frente": "Racismo x injúria racial hoje.", "verso": "Os dois são crimes de racismo: inafiançáveis e imprescritíveis. Injúria racial ofende a pessoa determinada; racismo atinge a coletividade (ex.: impedir acesso a lugar).", "explicacao": "Lei 7.716/1989, com a Lei 14.532/2023."}, {"id": 1000479, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "O que é racismo recreativo?", "verso": "Injúria racial praticada em contexto de descontração, diversão ou recreação. Gera aumento de pena.", "explicacao": "Lei 7.716/1989, art. 20-A (Lei 14.532/2023)."}, {"id": 1000480, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O STF equiparou a homofobia e a transfobia a quê?", "verso": "Ao crime de racismo, até que o Congresso edite lei específica.", "explicacao": "STF, ADO 26 e MI 4.733 (2019)."}, {"id": 1000481, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pares", "frente": "Identidade de gênero x orientação sexual.", "verso": "Identidade de gênero: como a pessoa se reconhece (homem, mulher, outro). Orientação sexual: por quem sente atração afetiva e sexual.", "explicacao": "São conceitos independentes."}, {"id": 1000482, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é a Lei do Minuto Seguinte?", "verso": "Lei que garante atendimento imediato, obrigatório e integral no SUS às vítimas de violência sexual.", "explicacao": "Lei 12.845/2013."}, {"id": 1000483, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é violência política contra a mulher?", "verso": "Ação ou omissão para impedir, obstaculizar ou restringir os direitos políticos da mulher.", "explicacao": "Lei 14.192/2021."}, {"id": 1000484, "trilha": "policial", "materia": "igual", "assunto": "Igualdade", "tipo": "pergunta", "frente": "As cotas raciais em concursos federais são constitucionais?", "verso": "Sim, segundo o STF.", "explicacao": "STF, ADC 41, que julgou constitucional a reserva de vagas da Lei 12.990/2014."}, {"id": 1000485, "trilha": "policial", "materia": "igual", "assunto": "Povos tradicionais", "tipo": "pergunta", "frente": "Qual o órgão federal responsável pela política indigenista?", "verso": "A Funai (Fundação Nacional dos Povos Indígenas).", "explicacao": "Vinculada ao Ministério dos Povos Indígenas."}, {"id": 1000486, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Como o Estatuto define a pessoa com deficiência?", "verso": "Quem tem impedimento de longo prazo de natureza física, mental, intelectual ou sensorial que, em interação com barreiras, pode obstruir sua participação plena na sociedade em igualdade de condições.", "explicacao": "Lei 13.146/2015, art. 2º."}, {"id": 1000487, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "certo_errado", "frente": "Certo ou errado? A deficiência afeta a plena capacidade civil da pessoa.", "verso": "Errado.", "explicacao": "Lei 13.146/2015, art. 6º."}, {"id": 1000488, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é adaptação razoável?", "verso": "Adaptações e ajustes necessários e adequados, sem ônus desproporcional, para garantir que a pessoa com deficiência exerça seus direitos em igualdade.", "explicacao": "Lei 13.146/2015, art. 3º, VI."}, {"id": 1000489, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Qual o crime previsto para quem discrimina pessoa em razão de sua deficiência?", "verso": "Reclusão de 1 a 3 anos e multa.", "explicacao": "Lei 13.146/2015, art. 88."}, {"id": 1000490, "trilha": "policial", "materia": "pcd", "assunto": "Convenção", "tipo": "pergunta", "frente": "Qual o status da Convenção da ONU sobre os Direitos das Pessoas com Deficiência no Brasil?", "verso": "Equivalente a emenda constitucional, por ter sido aprovada com o rito do art. 5º, § 3º.", "explicacao": "Decreto 6.949/2009."}, {"id": 1000491, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é aprendizado de máquina (machine learning)?", "verso": "Área da IA em que sistemas aprendem padrões a partir de dados, sem ser programados regra por regra.", "explicacao": "Ex.: reconhecimento facial, filtros de spam."}, {"id": 1000492, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é IA generativa?", "verso": "Sistemas que criam conteúdo novo (texto, imagem, áudio, vídeo) a partir de padrões aprendidos.", "explicacao": "Ex.: chatbots e geradores de imagem."}, {"id": 1000493, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é deepfake?", "verso": "Vídeo, áudio ou imagem falsos, gerados ou alterados por IA, que imitam pessoas reais.", "explicacao": "Risco para fraudes, golpes e desinformação."}, {"id": 1000494, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é viés algorítmico?", "verso": "Quando o sistema reproduz ou amplia preconceitos presentes nos dados de treinamento.", "explicacao": "Preocupação no uso de reconhecimento facial na segurança pública."}, {"id": 1000495, "trilha": "policial", "materia": "ia", "assunto": "Proteção de dados", "tipo": "pergunta", "frente": "Dados biométricos são que tipo de dado pessoal na LGPD?", "verso": "Dados pessoais sensíveis.", "explicacao": "Lei 13.709/2018, art. 5º, II."}, {"id": 1000496, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é desenvolvimento sustentável?", "verso": "Atender às necessidades do presente sem comprometer a capacidade das futuras gerações de atenderem às suas.", "explicacao": "Relatório Brundtland (1987)."}, {"id": 1000497, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quais os três pilares da sustentabilidade?", "verso": "Ambiental, social e econômico.", "explicacao": "Base do conceito de ESG."}, {"id": 1000498, "trilha": "policial", "materia": "sust", "assunto": "Agenda 2030", "tipo": "pergunta", "frente": "Quantos são os Objetivos de Desenvolvimento Sustentável da ONU?", "verso": "17 objetivos.", "explicacao": "Agenda 2030. O ODS 16 trata de paz, justiça e instituições eficazes."}, {"id": 1000499, "trilha": "policial", "materia": "sust", "assunto": "Gestão pública", "tipo": "pergunta", "frente": "O que é a A3P?", "verso": "Agenda Ambiental na Administração Pública, programa para adotar práticas sustentáveis nos órgãos públicos.", "explicacao": "Coordenada pelo Ministério do Meio Ambiente."}, {"id": 1000500, "trilha": "policial", "materia": "sust", "assunto": "Constituição", "tipo": "pergunta", "frente": "A quem a Constituição impõe o dever de defender o meio ambiente?", "verso": "Ao Poder Público e à coletividade, para as presentes e futuras gerações.", "explicacao": "CF, art. 225."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select count(*) as cartoes_policial_no_banco from public.cartoes where trilha = 'policial' and ativa;
